package com.fasterxml.jackson.dataformat.xml.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.PackageVersion;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.HashSet;
import java.util.Set;
import javax.xml.stream.XMLStreamReader;
import javax.xml.stream.XMLStreamWriter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class FromXmlParser_nextTextValue_TriageGen2Test {

    private FromXmlParser parser;

    @Mock
    private IOContext ioContext;
    @Mock
    private ObjectCodec codec;
    @Mock
    private XMLStreamReader xmlReader;
    @Mock
    private XmlXmlTokens xmlTokens; // Assuming XmlTokenStream is implemented via this mockable interface or equivalent
    @Mock
    private XmlReadContext parsingContext;
    @Mock
    private XmlReadContext parentContext;

    // Note: In a real Jackson environment, XmlTokenStream is an internal class. 
    // For the purpose of this unit test, we mock the behavior expected by the code.
    // Since the code uses _xmlTokens.next(), we assume _xmlTokens is an instance of a class providing these methods.
    // We will use reflection to inject these mocks into the parser.

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        parser = new FromXmlParser(ioContext, 0, 0, codec, xmlReader);

        // Injecting private fields via reflection to control the internal state for branch coverage
        setField(parser, "_xmlTokens", xmlTokens);
        setField(parser, "_parsingContext", parsingContext);
        setField(parser, "_mayBeLeaf", false);
        setField(parser, "_cfgNameForTextElement", "text_element");
        setField(parser, "_namesToWrap", null);
    }

    private void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testNextTextValue_WhenNextTokenIsString() throws IOException, NoSuchFieldException, IllegalAccessException {
        // Arrange: _nextToken is already set to VALUE_STRING
        setField(parser, "_nextToken", JsonToken.VALUE_STRING);
        setField(parser, "_currText", "hello");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("hello", result);
        assertNull(getFieldValue(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_WhenNextTokenIsOther() throws IOException, NoSuchFieldException, IllegalAccessException {
        // Arrange: _nextToken is not VALUE_STRING
        setField(parser, "_nextToken", JsonToken.START_OBJECT);
        setField(parser, "_currToken", null);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.START_OBJECT, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_StartElement_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setField(parser, "_mayBeLeaf", true);
        when(parsingContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(parsingContext);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.FIELD_NAME, getFieldValue(parser, "_nextToken"));
        assertEquals(JsonToken.START_OBJECT, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_StartElement_InArray() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setField(parser, "_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(true);
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT); // second call

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        verify(xmlTokens, atLeast(2)).next();
    }

    @Test
    public void testNextTextValue_StartElement_WithNamesToWrap() throws Exception {
        // Arrange
        Set<String> namesToWrap = new HashSet<>();
        namesToWrap.add("wrapMe");
        setField(parser, "_namesToWrap", namesToWrap);

        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        when(xmlTokens.getLocalName()).thenReturn("wrapMe");
        setField(parser, "_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(false);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        verify(xmlTokens).repeatStartElement();
        assertEquals(JsonToken.FIELD_NAME, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_EndElement_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END_ELEMENT);
        setField(parser, "_mayBeLeaf", true);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("", result);
        assertFalse((boolean) getFieldValue(parser, "_mayBeLeaf"));
        assertEquals(JsonToken.VALUE_STRING, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_EndElement_NotInArray() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END_ELEMENT);
        setField(parser, "_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(false);
        when(parsingContext.getParent()).thenReturn(parentContext);
        when(parentContext.getNamesToWrap()).thenReturn(null);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.END_OBJECT, getFieldValue(parser, "_currToken"));
        assertEquals(parentContext, getFieldValue(parser, "_parsingContext"));
    }

    @Test
    public void testNextTextValue_AttributeName_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_NAME);
        setField(parser, "_mayBeLeaf", true);
        when(xmlTokens.getText()).thenReturn("attrVal");
        when(parsingContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(parsingContext);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertFalse((boolean) getFieldValue(parser, "_mayBeLeaf"));
        assertEquals(JsonToken.FIELD_NAME, getFieldValue(parser, "_nextToken"));
        assertEquals("attrVal", getFieldValue(parser, "_currText"));
        assertEquals(JsonToken.START_OBJECT, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_AttributeName_NotMayBeLeaf() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_NAME);
        setField(parser, "_mayBeLeaf", false);
        when(xmlTokens.getLocalName()).thenReturn("attrName");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        verify(parsingContext).setCurrentName("attrName");
        assertEquals(JsonToken.FIELD_NAME, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_AttributeValue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_VALUE);
        when(xmlTokens.getText()).thenReturn("val");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals("val", getFieldValue(parser, "_currText"));
        assertEquals(JsonToken.VALUE_STRING, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setField(parser, "_mayBeLeaf", true);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("textContent", result);
        assertFalse((boolean) getFieldValue(parser, "_mayBeLeaf"));
        verify(xmlTokens).skipEndElement();
        assertEquals(JsonToken.VALUE_STRING, getFieldValue(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_NotMayBeLeaf() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setField(parser, "_mayBeLeaf", false);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        verify(parsingContext).setCurrentName("text_element");
        assertEquals(JsonToken.FIELD_NAME, getFieldValue(parser, "_currToken"));
        assertEquals(JsonToken.VALUE_STRING, getFieldValue(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_XmlEnd() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertNull(getFieldValue(parser, "_currToken"));
    }

    private Object getFieldValue(Object target, String name) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }
}
